using Kaff.Domain.DailyLogs;

namespace Kaff.Api.Features.DailyLogs.RecordCheckIn;

/// <summary>A check-in or check-out button press. Latitude and longitude are required by the domain: missing or invalid is refused. Accuracy is optional.</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="OccurredAt">The device time, with its offset, when the button was pressed. The server time is stamped on receipt and never taken from here.</param>
/// <param name="Kind"><c>CheckIn</c> or <c>CheckOut</c>. Any other value is refused.</param>
/// <param name="Latitude">Degrees. Null when the phone gave no location.</param>
/// <param name="Longitude">Degrees. Null when the phone gave no location.</param>
/// <param name="AccuracyMetres">The phone's accuracy radius in metres. Null when not reported.</param>
public sealed record Request(
    Guid? EntryId,
    DateTimeOffset? OccurredAt,
    DailyLogField Kind,
    double? Latitude,
    double? Longitude,
    double? AccuracyMetres);
